                }

                html[data-theme="light"] .site-selector-option__mark,
                html:not([data-theme="dark"]) .site-selector-option__mark {
                    color: #2d5fba;
                    background: #cfe1fb;
                }

                html[data-theme="light"] .site-selector-option__mark--all,
                html:not([data-theme="dark"]) .site-selector-option__mark--all {
                    color: #087ba5;
                    background: #d1efff;
                }

                html[data-theme="light"] .site-selector-option__mark--intl,
                html:not([data-theme="dark"]) .site-selector-option__mark--intl {
                    color: #5146b8;
                    background: #dedfff;
                }

                html[data-theme="light"] .site-selector-option.active .site-selector-option__mark,
                html:not([data-theme="dark"]) .site-selector-option.active .site-selector-option__mark {
                    color: #2358b8;
                    background: rgba(186, 210, 243, 0.82);
                }

                html[data-theme="light"] .site-selector-option__label,
                html:not([data-theme="dark"]) .site-selector-option__label {
                    color: #273244;
                }

                html[data-theme="light"] .site-selector-option__hint,
                html:not([data-theme="dark"]) .site-selector-option__hint {
                    color: rgba(71, 85, 105, 0.84);
                }

                html[data-theme="light"] .site-selector-option__check,
                html:not([data-theme="dark"]) .site-selector-option__check {
                    color: #2358b8;
                    background: rgba(213, 228, 247, 0.82);
                }

                @media (max-width: 900px) {
                    .admin-site-filter-toolbar {
                        gap: 8px;
                    }

                    .admin-theme-toggle-btn {
                        width: 36px;
                        height: 36px;
                        border-radius: 10px;
                    }

                    .site-selector-btn {
                        min-width: 60px;
                        height: 36px;
                        border-radius: 12px;
                        gap: 6px;
                    }

                    .site-selector-kicker {
                        display: none;
                    }

                    .site-selector-label {
                        max-width: 40px;
                    }

                    .site-selector-menu {
                        width: 168px;
                    }
                }


