                        .tree-category-header:hover {
                            background: rgba(255, 255, 255, 0.05);
                        }

                        .tree-category-header.active {
                            background: rgba(107, 158, 206, 0.1);
                        }

                        .tree-chevron {
                            width: 16px;
                            font-size: 10px;
                            color: rgba(255, 255, 255, 0.4);
                            transition: transform 0.2s ease;
                            margin-right: 6px;
                        }

                        .tree-category.expanded .tree-chevron {
                            transform: rotate(90deg);
                        }

                        .tree-folder-icon {
                            font-size: 16px;
                            color: rgba(255, 255, 255, 0.5);
                            margin-right: 10px;
                        }

                        .tree-folder-icon--recycle-bin {
                            color: #ef4444;
                        }

                        .tree-category.expanded .tree-folder-icon:not([class*="category-color--"]) {
                            color: #6b9ece;
                        }

                        .tree-category-name {
                            flex: 1;
                            min-width: 0;
                            font-size: 16px;
                            font-weight: 500;
                            color: rgba(255, 255, 255, 0.85);
