                            color: rgba(255, 255, 255, 0.4);
                            padding: 3px 10px;
                            background: rgba(255, 255, 255, 0.05);
                            border-radius: 10px;
                            user-select: none;
                            -webkit-user-select: none;
                            -webkit-touch-callout: none;
                        }

                        .tree-category-count--danger {
                            background: rgba(239, 68, 68, 0.2);
                            color: #ef4444;
                        }

                        /* Product Children (Indented) */
                        .tree-children {
                            display: none;
                            padding-left: 42px;
                        }

                        .tree-category.expanded .tree-children {
                            display: block;
                        }

                        .tree-product-item {
                            display: flex;
                            align-items: center;
                            padding: 8px 15px 8px 10px;
                            margin: 2px 10px 2px 0;
                            border-radius: 6px;
