                        .tree-product-item--drag-dim {
                            opacity: 0.4;
                        }

                        .tree-product-item--deleted {
                            opacity: 0.6;
                        }

                        /* Drag Handle */
                        .tree-drag-handle {
                            font-size: 10px;
                            color: rgba(255, 255, 255, 0.2);
                            margin-right: 6px;
                            cursor: grab;
                            opacity: 0;
                            transition: opacity 0.15s;
                        }

                        .tree-product-item:hover .tree-drag-handle {
                            opacity: 1;
