                        .shop-import-tree-skeleton {
                            display: flex;
                            flex-direction: column;
                            gap: 14px;
                        }

                        .shop-import-tree-skeleton-group {
                            padding: 16px;
                            border-radius: 16px;
                            border: 1px solid rgba(255, 255, 255, 0.06);
