                        /* Drop Zone Highlight */
                        .tree-category-header.drag-over {
                            background: rgba(107, 158, 206, 0.2) !important;
                            border: 1px dashed #6b9ece;
                            transform: scale(1.02);
                        }

                        .tree-category-header.drag-over .tree-folder-icon {
                            color: #6b9ece;
                            animation: folderPulse 0.5s ease infinite alternate;
                        }

                        @keyframes folderPulse {
                            from {
                                transform: scale(1);
                            }

                            to {
                                transform: scale(1.15);
                            }
                        }

                        /* Drop Indicator Line */
                        .drop-indicator {
                            height: 2px;
                            background: #6b9ece;
                            margin: 2px 0;
