                            border-color: rgba(107, 158, 206, 0.4);
                            color: #6b9ece;
                        }

                        /* Context Menu */
                        .tree-context-menu {
                            position: absolute;
                            min-width: 160px;
                            padding: 6px;
                            background: linear-gradient(145deg, rgba(35, 40, 60, 0.98), rgba(20, 25, 40, 0.98));
                            backdrop-filter: blur(24px);
                            border: 1px solid rgba(255, 255, 255, 0.12);
                            border-radius: 10px;
                            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
                            z-index: 9999;
                            display: none;
                            user-select: none;
                            -webkit-user-select: none;
                            -webkit-touch-callout: none;
                        }

                        .tree-context-menu.show {
                            display: block;
                        }

                        .tree-context-menu--anchor-left {
                            left: 0;
                            right: auto;
                        }

                        .tree-context-menu--anchor-right {
                            right: 0;
                            left: auto;
                        }

                        .tree-context-menu--anchor-down {
                            top: calc(100% + 8px);
                            bottom: auto;
                        }

                        .tree-context-menu--anchor-up {
                            bottom: calc(100% + 8px);
                            top: auto;
                        }

                        .context-menu-item {
                            display: flex;
                            align-items: center;
                            gap: 10px;
                            padding: 10px 12px;
                            border-radius: 6px;
                            font-size: 13px;
                            color: rgba(255, 255, 255, 0.8);
                            cursor: pointer;
                            transition: all 0.15s;
                            user-select: none;
                            -webkit-user-select: none;
                            -webkit-touch-callout: none;
                        }

                        .context-menu-item:hover {
                            background: rgba(255, 255, 255, 0.08);
                        }

                        .context-menu-item i {
                            width: 16px;
                            text-align: center;
                            font-size: 12px;
                            color: rgba(255, 255, 255, 0.5);
                        }

                        .context-menu-item.danger {
                            color: #e57373;
                        }

                        .context-menu-item.danger i {
                            color: #e57373;
                        }

                        .context-menu-divider {
                            height: 1px;
                            background: rgba(255, 255, 255, 0.1);
                            margin: 4px 0;
                        }

                        /* Color Options */
                        .context-menu-colors {
                            display: flex;
                            gap: 6px;
                            padding: 8px 12px;
                        }

                        .color-option {
                            width: 20px;
                            height: 20px;
                            border-radius: 50%;
                            cursor: pointer;
                            border: 2px solid transparent;
                            transition: all 0.15s;
                        }

                        .color-option:hover {
                            transform: scale(1.15);
                        }

                        .color-option.selected {
                            border-color: white;
                        }

                        /* Mobile optimizations for context menu */
                        @media (max-width: 768px) {
                            .tree-context-menu {
                                min-width: 160px;
                                padding: 4px;
                            }

                            .context-menu-item {
                                padding: 10px 12px;
                                font-size: 13px;
                                -webkit-tap-highlight-color: transparent;
                            }

                            .context-menu-item:active {
                                background: rgba(255, 255, 255, 0.15);
                            }

                            .context-menu-colors {
                                gap: 8px;
                                padding: 8px 12px;
                            }

                            .color-option {
                                width: 24px;
                                height: 24px;
                                border-width: 2px;
                                -webkit-tap-highlight-color: transparent;
                            }

                            .color-option:active {
                                transform: scale(0.9);
                            }

                            /* Center import button on mobile */
                            #importButtonContainer {
                                justify-content: center !important;
                            }
                        }


