/* 20260430_ADMIN_STUDIO_MARKETING_RECENT_ASSET_GRID_1 */
.marketing-asset-center__list {
    display: grid;
    gap: 12px;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr));
    align-items: stretch;
}

.marketing-asset-center__list-item {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
}

.marketing-asset-center__list-item-copy {
    min-width: 0;
    display: grid;
    gap: 8px;
}

.marketing-asset-center__family-action,
.marketing-asset-center__detail-btn {
    border: 1px solid rgba(56, 189, 248, 0.26);
    background: rgba(56, 189, 248, 0.14);
    color: #e0f2fe;
    border-radius: 999px;
    padding: 8px 14px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease;
}

.marketing-asset-center__detail-btn {
    align-self: center;
    justify-self: end;
    white-space: nowrap;
}

.marketing-asset-center__family-action:hover,
.marketing-asset-center__detail-btn:hover {
    transform: translateY(-1px);
    background: rgba(56, 189, 248, 0.22);
    border-color: rgba(125, 211, 252, 0.46);
}

.marketing-asset-center__family-action:disabled {
    cursor: not-allowed;
    opacity: 0.52;
    transform: none;
}

.marketing-asset-center__error,
.marketing-asset-center__empty {
    padding: 18px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    color: #e2e8f0;
    font-size: 14px;
    line-height: 1.6;
}

@media (max-width: 860px) {
    .marketing-asset-center__section-head,
    .marketing-asset-center__list-item,
    .marketing-asset-center__family-top,
    .marketing-asset-center__workflow-top {
        flex-direction: column;
        align-items: flex-start;
    }

    .marketing-asset-center__detail-btn,
    .marketing-asset-center__family-action {
        width: 100%;
        justify-content: center;
    }
}

select[data-shop-custom-select="true"].shop-native-select--hidden {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    opacity: 0 !important;
    pointer-events: none !important;
    transform: translateY(-9999px) !important;
}

.shop-custom-select {
    position: relative;
    display: inline-flex;
    width: 100%;
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
    box-shadow: none !important;
    overflow: visible;
}

.shop-custom-select.shop-product-toolbar-select,
.shop-custom-select.shop-orders-filter-select {
    min-width: 160px;
    max-width: 220px;
    flex: 0 1 220px;
}

.shop-custom-select.shop-orders-filter-select {
    min-width: 148px;
    max-width: 156px;
    flex: 0 0 156px;
}

.shop-custom-select.shop-delivery-filter {
    min-width: 160px;
}

#module-homepage .hp-form-grid .hp-field .shop-custom-select {
    width: 100%;
}

.shop-custom-select__trigger {
    width: 100%;
    min-height: var(--admin-studio-control-height, 46px);
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 0 16px;
    border-radius: var(--admin-studio-radius-control, 14px);
    border: 1px solid rgba(148, 163, 184, 0.24);
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.03)),
        rgba(15, 23, 42, 0.68);
    color: #f8fafc;
    font-size: 0.92rem;
    text-align: left;
    cursor: pointer;
    transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.shop-custom-select__trigger:hover {
    border-color: rgba(125, 211, 252, 0.32);
    background:
        linear-gradient(180deg, rgba(125, 211, 252, 0.08), rgba(255, 255, 255, 0.03)),
        rgba(15, 23, 42, 0.74);
    box-shadow: 0 12px 28px rgba(2, 6, 23, 0.18);
}

.shop-custom-select__trigger:focus-visible {
    outline: none;
    border-color: rgba(125, 211, 252, 0.48);
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.18);
}

.shop-custom-select.is-open .shop-custom-select__trigger {
    border-color: rgba(125, 211, 252, 0.42);
    background:
        linear-gradient(180deg, rgba(125, 211, 252, 0.1), rgba(255, 255, 255, 0.04)),
        rgba(15, 23, 42, 0.8);
}

.shop-custom-select.is-disabled .shop-custom-select__trigger {
    opacity: 0.58;
    cursor: not-allowed;
    box-shadow: none;
}

.shop-custom-select__label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.shop-custom-select__icon {
    flex-shrink: 0;
    font-size: 0.8rem;
    color: rgba(226, 232, 240, 0.74);
    transition: transform 0.18s ease;
}

.shop-custom-select.is-open .shop-custom-select__icon {
    transform: rotate(180deg);
}

.shop-custom-select__menu {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    right: 0;
    z-index: 120;
    display: grid;
    gap: 6px;
    max-height: 280px;
    padding: 8px;
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background:
        linear-gradient(180deg, rgba(15, 23, 42, 0.96), rgba(15, 23, 42, 0.92)),
        radial-gradient(circle at top right, rgba(56, 189, 248, 0.16), transparent 38%);
    box-shadow: 0 24px 56px rgba(2, 6, 23, 0.32);
    backdrop-filter: blur(18px);
    opacity: 0;
    transform: translateY(-6px);
    pointer-events: none;
    overflow-y: auto;
}

.shop-custom-select.is-open .shop-custom-select__menu {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
}

.shop-custom-select__option {
    width: 100%;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 11px 12px;
    border: 1px solid transparent;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.02);
    color: #e2e8f0;
    font-size: 0.9rem;
    text-align: left;
    cursor: pointer;
    transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.shop-custom-select__option:hover {
    background: rgba(125, 211, 252, 0.1);
    border-color: rgba(125, 211, 252, 0.2);
    transform: translateY(-1px);
}

.shop-custom-select__option.is-selected {
    background: rgba(61, 90, 128, 0.28);
    border-color: rgba(125, 211, 252, 0.28);
    color: #f8fafc;
}

.shop-custom-select__option[aria-disabled="true"] {
    opacity: 0.46;
    cursor: not-allowed;
    transform: none;
}

.shop-custom-select__option-copy {
    flex: 1;
    min-width: 0;
}

.shop-custom-select__option-check {
    color: #7dd3fc;
    flex-shrink: 0;
}

@media (max-width: 860px) {
    .shop-custom-select.shop-product-toolbar-select,
    .shop-custom-select.shop-orders-filter-select,
    .shop-custom-select.shop-delivery-filter {
        min-width: 100%;
        max-width: none;
        flex: 1 1 100%;
    }
