    transition: opacity 140ms ease, transform 140ms ease, visibility 140ms ease;
}

html[data-theme="light"] .admin-command-center__dock-btn:focus-visible .admin-command-center__dock-label,
html:not([data-theme="dark"]) .admin-command-center__dock-btn:focus-visible .admin-command-center__dock-label {
    transform: translate(0, -50%);
}

html[data-theme="light"] .admin-command-center__panel,
html:not([data-theme="dark"]) .admin-command-center__panel {
    top: 50% !important;
    right: 76px !important;
    bottom: auto !important;
    left: auto !important;
    width: min(430px, calc(100vw - 126px)) !important;
    max-height: calc(100vh - 112px) !important;
    transform: translate(
        var(--admin-command-panel-shift-x, 14px),
        calc(var(--admin-command-panel-open-y, -50%) + var(--admin-command-panel-shift-y, 0px))
    ) scale(var(--admin-command-panel-start-scale, 0.78));
    transform-origin: var(--admin-command-panel-origin-x, 100%) var(--admin-command-panel-origin-y, 50%);
}

html[data-theme="light"] .admin-command-center__panel.is-open,
html:not([data-theme="dark"]) .admin-command-center__panel.is-open {
    opacity: 1 !important;
    visibility: visible !important;
    pointer-events: auto !important;
